const msg = $('Telegram Trigger1').first().json.message;

// 1. Guard: check for an attached photo
if (!msg.photo || msg.photo.length === 0) {
  throw new Error('No photo attached. Please send a product image with quantity in the caption.');
}

const rawCaption = (msg.caption || '').trim();
if (!rawCaption) {
  throw new Error('No caption found. Please type the quantity (e.g., "30" or "30 200rs") in the caption.');
}

// 2. Clean and standardize the lines into an array
const captionLines = rawCaption.split('\n').map(line => line.trim()).filter(line => line.length > 0);

let extractedPrice = null;
let extractedQuantity = null;

// Helper to check if a line represents a price (contains rs, ₹, rupees, or inr)
const isPriceString = (str) => /(?:rs|₹|inr|rupees)/i.test(str);

// 3. Process lines safely
if (captionLines.length === 1) {
  // Single-line fallback parsing
  const singleLine = captionLines[0];
  const priceMatch = singleLine.match(/(?:for\s*)?(\d+(?:\.\d+)?)\s*(?:rs|₹|inr|rupees)/i);
  if (priceMatch) {
    extractedPrice = parseFloat(priceMatch[1]);
    // Strip out the price part to find a separate standalone number for quantity
    const remainingText = singleLine.replace(priceMatch[0], '').trim();
    const qtyMatch = remainingText.match(/(\d+)/);
    if (qtyMatch) extractedQuantity = parseInt(qtyMatch[1], 10);
  } else {
    // If no currency marker exists, treat the single line text number as a quantity count
    const qtyMatch = singleLine.match(/(\d+)/);
    if (qtyMatch) extractedQuantity = parseInt(qtyMatch[1], 10);
  }
} else {
  // Multi-line intelligent scanning (handles layouts like "200rs\n30")
  for (const line of captionLines) {
    if (isPriceString(line)) {
      const priceMatch = line.match(/(\d+(?:\.\d+)?)/);
      if (priceMatch) extractedPrice = parseFloat(priceMatch[1]);
    } else {
      const qtyMatch = line.match(/(\d+)/);
      if (qtyMatch) extractedQuantity = parseInt(qtyMatch[1], 10);
    }
  }
}

// 4. Default fallbacks if parsing steps came up short
if (!extractedQuantity) extractedQuantity = 1; 

const photo = msg.photo[msg.photo.length - 1];

return [{
  json: {
    file_id: photo.file_id,
    chat_id: msg.chat.id,
    from_id: msg.from.id,
    caption: rawCaption,
    extracted_quantity: extractedQuantity,
    extracted_price: extractedPrice
  }
}];

