parameters.jsCode:
const items = $input.all();
const extracted = $('Validate & Extract Message1').first().json;

for (let item of items) {
  item.json.raw_caption = extracted.caption;
  item.json.chat_id = extracted.chat_id;
}

return items;

const imageData = $input.first();
const fileUrl = `https://api.telegram.org/file/bot${$vars.telegram_api_key}/${imageData.json.result.file_path}`;
const rawCaption = $('Validate & Extract Message1').first().json.caption || '';

const body = {
  contents: [
    {
      parts: [
        {
          file_data: {
            mime_type: "image/jpeg",
            file_uri: fileUrl
          }
        },
        {
          text: `SYSTEM INSTRUCTIONS:\nYou are a product identification assistant for an Indian retail store (kirana shop). You will analyze a product image and return inventory data.\n\nSTRICT OUTPUT RULES:\n- Return ONLY a raw JSON object\n- No markdown fences, no backticks, no explanation, no preamble\n- First character of your response must be { and last must be }\n\nFIELD RULES:\n- name: Full product name with brand + variant + size/weight as printed on packaging.\n- category: MUST be exactly one of: Grocery, Dairy, Biscuits, Snacks, Instant, Hygiene, Beverages, Stationary, Other\n- price: Retail price in INR as a plain integer. No ₹ symbol. If visible on packaging use that. Otherwise estimate Indian market price.\n- unit: MUST be exactly one of: kg, L, pkt, btl, pcs, bag, box\n- quantity: Extract from user caption below. A standalone number means units being added. If no number found, use 1.\n\nUSER CAPTION:\n"${rawCaption}"\n\nCAPTION PARSING RULES:\n- Standalone number ("20") → quantity is 20\n- Number with currency ("10rs", "₹10") → that is price, not quantity\n- Both present ("20\\n10rs") → quantity is 20, price is 10\n- If caption gives a price, it ALWAYS overrides your estimate\n\nNow return the JSON object:`
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.1,
    maxOutputTokens: 1024,
    responseMimeType: "application/json"
  }
};

return [{ json: { body: JSON.stringify(body) } }];

const inputJson = $input.first().json;

// Read from Gemini HTTP response structure
let rawText = inputJson?.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (!rawText) {
  throw new Error('Gemini returned an empty response. Check model name and token limit.');
}

// Extract JSON object if wrapped in conversational text or markdown
if (rawText.includes('{')) {
  rawText = rawText.substring(rawText.indexOf('{'), rawText.lastIndexOf('}') + 1);
}

// Strip any remaining markdown fences
const cleaned = rawText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

let product;
try {
  product = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Invalid JSON from Gemini: ' + cleaned);
}

// Safe fallback layer
const finalName     = product.name     || 'Unknown Product';
const finalCategory = product.category || 'Other';
const finalPrice    = product.price    != null ? Number(product.price)    : 0;
const finalUnit     = product.unit     || 'pcs';
const finalQuantity = product.quantity != null ? Number(product.quantity) : 1;

// chat_id and raw_caption are passed forward from the Build Gemini Request code node
const finalChatId   = inputJson.chat_id    || 0;

const product_id = 'p_' + finalName
  .toLowerCase()
  .replace(/[^a-z0-9]/g, '_')
  .replace(/_+/g, '_')
  .slice(0, 30);

return [{
  json: {
    product_id,
    name:           finalName,
    category:       finalCategory,
    price:          finalPrice,
    unit:           finalUnit,
    quantity: finalQuantity,
    min_threshold:  10,
  }
}];
